css:
.aph-vt { font-family: "Times New Roman", Times, serif; font-size: 12.5px; color: #000; line-height: 1.35; }
.aph-vt table { width: 100%; border-collapse: collapse; font-size: inherit; }
.aph-vt .aph-head td, .aph-vt .aph-title td, .aph-vt .aph-sign td { border: 0; vertical-align: top; padding: 0; }
.aph-vt .aph-mau { width: 42%; text-align: center; font-size: 11.5px; }
.aph-vt .aph-title td { padding: 8px 0 4px; }
.aph-vt .aph-side { width: 24%; }
.aph-vt .aph-center { text-align: center; }
.aph-vt .aph-name { font-size: 17px; font-weight: bold; letter-spacing: 0.5px; }
.aph-vt .aph-date { font-style: italic; }
.aph-vt .aph-noco { padding-top: 22px !important; padding-left: 12px !important; }
.aph-vt .aph-info { margin: 4px 0 6px; line-height: 1.6; }
.aph-vt .aph-sec { font-weight: bold; margin: 10px 0 4px; }
.aph-vt .aph-tbl th, .aph-vt .aph-tbl td { border: 1px solid #000; padding: 3px 4px; }
.aph-vt .aph-tbl th { text-align: center; font-weight: bold; vertical-align: middle; }
.aph-vt .aph-tbl .aph-letter td { text-align: center; font-weight: bold; padding: 1px; }
.aph-vt .aph-tbl .c { text-align: center; }
.aph-vt .aph-tbl .r { text-align: right; white-space: nowrap; }
.aph-vt .aph-tbl small { font-size: 10.5px; }
.aph-vt .c-stt { width: 5%; }
.aph-vt .c-ma { width: 14%; }
.aph-vt .c-dvt { width: 7%; }
.aph-vt .c-sl { width: 10%; }
.aph-vt .c-tien { width: 12%; }
.aph-vt .aph-sign-date { text-align: right; font-style: italic; margin-top: 10px; padding-right: 4%; }
.aph-vt .aph-sign td { text-align: center; padding-top: 4px; }
.aph-vt .aph-sign-name { margin-top: 70px; }
.aph-vt .aph-qh { width: 50%; text-align: center; }
.aph-vt .aph-lien { font-style: italic; margin-top: 2px; }
.aph-vt .aph-party { font-weight: bold; margin-top: 6px; }
.aph-vt .aph-tbl .aph-sum td { font-weight: bold; }
.aph-vt .aph-tbl .aph-sum .l { text-align: right; }
.aph-vt .c-lo { width: 11%; }
.aph-vt .aph-tc { line-height: 1.9; font-size: 13.5px; }
.aph-vt .aph-tong { width: 55%; margin-left: 45%; margin-top: -1px; }
.aph-vt .aph-tong .l { text-align: left; }
.aph-vt .aph-tbl th { color: #000; }

/* Chứng từ vận dụng TT133/TT99; giữ khổ giấy do người dùng chọn, không ép A5 cho phiếu dài. */
.aph-vt .aph-state { text-align:center; font-weight:bold; border:1px solid #555; padding:3px; margin:3px 0; }
.aph-vt .aph-head { page-break-inside:avoid; break-inside:avoid; }
.aph-vt thead { display:table-header-group; }
.aph-vt tr { page-break-inside:avoid; break-inside:avoid; }
.aph-vt .aph-sign { page-break-inside:avoid; break-inside:avoid; }
.aph-vt .aph-sign td { min-width:15%; height:92px; }
.aph-vt .aph-mau { overflow-wrap:break-word; }

html:
{#- Phiếu thu (01-TT) / phiếu chi (02-TT) in từ Thanh toán (Payment Entry).
    Thu hay chi theo phía tài khoản tiền mặt; tiền gửi ngân hàng in chứng từ thu/chi ngân hàng (không mẫu).
    Căn cứ mẫu theo công ty: APH TT133/2016, VH TT99/2025. Lý do viết tiếng Việt (ERPNext tự sinh tiếng Anh). -#}
{%- set cty = kh_aph_cong_ty(doc.company) -%}
{%- set nc = kh_aph_no_co(doc) -%}
{%- set p = kh_aph_thu_chi(doc) -%}
{%- set cham = ".................................................." -%}
{%- set pf = kh_aph_mau_info(doc.company, p.kieu if p.tien_mat else "noi_bo") -%}
<div class="aph-vt">
{% if doc.docstatus == 0 %}<div class="aph-state">BẢN NHÁP - CHƯA GHI SỔ</div>{% elif doc.docstatus == 2 %}<div class="aph-state">CHỨNG TỪ ĐÃ HỦY - CHỈ ĐỂ ĐỐI CHIẾU</div>{% endif %}
<table class="aph-head"><tr>
  <td><b>Đơn vị:</b> {{ cty.ten }}{% if cty.dia_chi %}<br><b>Địa chỉ:</b> {{ cty.dia_chi }}{% endif %}</td>
  <td class="aph-mau"><b>{{ pf.nhan | e }}</b>{% if pf.can_cu %}<br><i>{{ pf.can_cu | e }}</i>{% endif %}</td>
</tr></table>
<table class="aph-title"><tr>
  <td class="aph-side"></td>
  <td class="aph-center">
    <div class="aph-name">{{ p.tieu_de }}</div>
    <div class="aph-date">{{ kh_aph_ngay(doc.posting_date) }}</div>
    <div>{% if p.tien_mat %}Quyển số: ................ &nbsp;{% endif %}Số: {{ doc.name }}</div>
  </td>
  <td class="aph-side aph-noco">Nợ: {{ nc.no }}<br>Có: {{ nc.co }}</td>
</tr></table>

<div class="aph-info aph-tc">
  {%- if p.kieu == "thu" %}
  <div>Họ và tên người nộp tiền: <b>{{ p.nguoi or cham }}</b></div>
  {%- elif p.kieu == "chi" %}
  <div>Họ và tên người nhận tiền: <b>{{ p.nguoi or cham }}</b></div>
  {%- endif %}
  {%- if p.kieu != "chuyen" %}
  <div>Địa chỉ: {{ p.dia_chi or cham }}</div>
  {%- endif %}
  <div>{{ "Lý do nộp" if p.kieu == "thu" else ("Lý do chi" if p.kieu == "chi" else "Nội dung") }}: {{ p.ly_do }}</div>
  <div>Số tiền: <b>{{ p.so_tien }} {{ p.tien_te }}</b> &nbsp;<i>(Viết bằng chữ): {{ p.bang_chu }}</i></div>
  {%- if p.ngoai_te %}
  <div>+ Tỷ giá ngoại tệ: {{ p.ty_gia }} &nbsp;&nbsp; + Số tiền quy đổi: {{ p.quy_doi }} đồng</div>
  {%- endif %}
  {%- if not p.tien_mat %}
  <div>Tài khoản ngân hàng: {{ p.tai_khoan }}{% if p.tham_chieu %} &nbsp; Số tham chiếu: {{ p.tham_chieu }}{% endif %}</div>
  {%- endif %}
  <div>Kèm theo: ............ chứng từ gốc.</div>
</div>

<div class="aph-sign-date">{{ kh_aph_ngay(doc.posting_date) }}</div>
<table class="aph-sign"><tr>
  <td><b>{{ pf.nguoi_duyet | e }}</b><br><i>(Ký, họ tên, đóng dấu)</i></td>
  <td><b>{{ pf.ke_toan_truong | e }}</b><br><i>(Ký, họ tên)</i></td>
  {%- if p.tien_mat and p.kieu == "thu" %}
  <td><b>Người nộp tiền</b><br><i>(Ký, họ tên)</i></td>
  <td><b>Người lập phiếu</b><br><i>(Ký, họ tên)</i><div class="aph-sign-name">{{ kh_aph_ten_nguoi(doc.owner) }}</div></td>
  <td><b>Thủ quỹ</b><br><i>(Ký, họ tên)</i></td>
  {%- elif p.tien_mat and p.kieu == "chi" %}
  <td><b>Thủ quỹ</b><br><i>(Ký, họ tên)</i></td>
  <td><b>Người lập phiếu</b><br><i>(Ký, họ tên)</i><div class="aph-sign-name">{{ kh_aph_ten_nguoi(doc.owner) }}</div></td>
  <td><b>Người nhận tiền</b><br><i>(Ký, họ tên)</i></td>
  {%- else %}
  <td><b>Người lập</b><br><i>(Ký, họ tên)</i><div class="aph-sign-name">{{ kh_aph_ten_nguoi(doc.owner) }}</div></td>
  {%- endif %}
</tr></table>
{%- if p.tien_mat and p.kieu in ("thu", "chi") %}
<div class="aph-info aph-tc">
  <div>Đã nhận đủ số tiền (viết bằng chữ): {{ cham }}{{ cham }}</div>
  {% if not p.ngoai_te %}<div>+ Tỷ giá ngoại tệ: ........................ &nbsp; + Số tiền quy đổi: ........................</div>{% endif %}
  {% if pf.che_do in ("133", "99") %}<div><i>(Liên gửi ra ngoài phải đóng dấu)</i></div>{% endif %}
</div>
{%- endif %}
</div>
